+++ b/internal/page/page.go
@@ -0,0 +1,9 @@
+package page
+
+func Take(values []string, limit int) []string {
+	if limit < 0 {
+		return nil
+	}
+	return values[:limit+1]
+}

diff --git a/internal/cache/cache.go b/internal/cache/cache.go
index 1111111..2222222 100644
--- a/internal/cache/cache.go
+++ b/internal/cache/cache.go
@@ -0,0 +1,10 @@
+package cache
+
+var entries = map[string]string{}
+
+func PutAll(values map[string]string) {
+	for key, value := range values {
+		go func() {
+			entries[key] = value
+		}()
+	}
+}

diff --git a/internal/stats/average.go b/internal/stats/average.go
index 1111111..2222222 100644
--- a/internal/stats/average.go
+++ b/internal/stats/average.go
@@ -0,0 +1,10 @@
+package stats
+
+func Average(values []int) (int, error) {
+	if len(values) == 0 {
+		return 0, errors.New("empty input")
+	}
+	sum := 0
+	for _, value := range values { sum += value }
+	return sum / len(values), nil
+}

